import pytest
from solution import word_wrap


def test_basic_wrap():
    assert word_wrap('The quick brown fox jumps over the lazy dog', 10) == [
        'The quick',
        'brown fox',
        'jumps over',
        'the lazy',
        'dog'
    ]


def test_exact_fit():
    assert word_wrap('hello world', 11) == ['hello world']


def test_single_word_longer_than_width():
    assert word_wrap('supercalifragilistic', 5) == ['supercalifragilistic']


def test_empty_string():
    assert word_wrap('', 5) == []


def test_single_word_exact_width():
    assert word_wrap('hello', 5) == ['hello']


def test_multiple_spaces():
    assert word_wrap('a  b', 2) == ['a', 'b']


def test_unicode():
    assert word_wrap('héllo wörld', 6) == ['héllo', 'wörld']


def test_width_one():
    assert word_wrap('a b c', 1) == ['a', 'b', 'c']


def test_trailing_space():
    assert word_wrap('hello ', 5) == ['hello', '']


def test_negative_width_raises():
    with pytest.raises(ValueError):
        word_wrap('hello', -1)


def test_zero_width_raises():
    with pytest.raises(ValueError):
        word_wrap('hello', 0)


def test_non_string_text_raises():
    with pytest.raises(TypeError):
        word_wrap(123, 5)


def test_non_integer_width_raises():
    with pytest.raises(TypeError):
        word_wrap('hello', '5')


def test_preserves_case_and_punctuation():
    assert word_wrap('Hello, World!', 7) == ['Hello,', 'World!']


def test_long_text_multiple_lines():
    text = 'This is a longer piece of text that should wrap across several lines'
    assert word_wrap(text, 8) == [
        'This is',
        'a longer',
        'piece of',
        'text',
        'that',
        'should',
        'wrap',
        'across',
        'several',
        'lines'
    ]
